"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _include_target(line):
    """Return the include path if ``line`` is an ``@include`` directive."""
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _expand_lines(lines, path, stack):
    """Expand ``@include`` directives in ``lines`` read from ``path``."""
    base = os.path.dirname(os.path.abspath(path))
    stack = stack + [os.path.realpath(path)]
    out = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            out.append(line)
            continue
        child = os.path.join(base, os.path.expanduser(target))
        real = os.path.realpath(child)
        if real in stack:
            chain = " -> ".join(stack + [real])
            raise ConfigError("include cycle detected: {}".format(chain))
        if not os.path.isfile(child):
            raise ConfigError("included file not found: {}".format(child))
        try:
            with open(child, "r", encoding="utf-8") as fh:
                child_lines = fh.read().splitlines()
        except OSError as exc:
            raise ConfigError("cannot read included file {}: {}".format(child, exc))
        out.extend(_expand_lines(child_lines, child, stack))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file (recursively). Relative paths are resolved against the
    directory of the including file. Missing targets and include cycles raise
    :class:`~miniconf.errors.ConfigError`.
    """
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    return parse_lines(_expand_lines(lines, path, []))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
